document.querySelectorAll('.s9-card').forEach(card => {
    const rightButton = document.createElement('button');
    rightButton.className = 's9-right';
    rightButton.textContent = '→';
    card.appendChild(rightButton);

    const leftButton = document.createElement('button');
    leftButton.className = 's9-left';
    leftButton.textContent = '←';
    card.appendChild(leftButton);

    rightButton.addEventListener('click', function() {
        const currentList = card.parentElement;
        const nextList = currentList.nextElementSibling;
        if (nextList) {
            nextList.querySelector('ul').appendChild(card);
        }
    });

    leftButton.addEventListener('click', function() {
        const currentList = card.parentElement;
        const previousList = currentList.previousElementSibling;
        if (previousList) {
            previousList.querySelector('ul').appendChild(card);
        }
    });
});

